/* This is the default QMI_WDS command buffer. Make sure that it does not grow
 * beyond 512 bytes. In case you need a command buffer larger than 512 bytes,
 * declare a separate structure. */
typedef struct
{
  uint16  cmd_id; /* qmi_cmd_id_e_type */
  uint32  subscription_id;
  union
  {
    struct
    {
      uint8 clid;
    } send_pkt_stats;

    struct
    {
      ps_phys_link_type          *phys_link_ptr;
      ps_iface_event_enum_type   event;
      ps_iface_event_info_u_type event_info;
      void                       *user_data_ptr;
    } phys_link_status;

    struct
    {
      ps_iface_type              *iface_ptr;
      ps_iface_event_enum_type   event;
      ps_iface_event_info_u_type event_info;
      void                       *wds_sp;
    } iface_info;

    struct
    {
      ps_iface_event_enum_type     event;
      ps_iface_type               *iface_ptr;
      ps_iface_event_info_u_type   event_info;
      ps_iface_name_enum_type      iface_name;
    } dun_call_info;

    struct
    {
      uint32     new_pref_system;
    } pref_system;

    struct
    {
      uint32     status;
      uint8      call_type;
    } data_call_status;

#ifdef FEATURE_DATA_IS707
    struct
    {
      ds707_call_throttle_info throttled_delay;
      int16          ps_errno;
    } call_throttle_info;
#endif /*FEATURE_DATA_IS707*/

    struct
    {
      qmi_wdsi_dun_ctrl_event_e_type event_type;
      ps_sys_tech_enum_type          tech_type;
      unsigned char                  cb_data;
      boolean                        call_allowed;
      ps_iface_net_down_reason_type  net_down_reason;
    } dun_ctrl_event_info;

    qmi_wdsi_evdo_page_monitor_period epmp;

    struct
    {
      int16     evt;
      ps_hdr_slotted_mode_failure_code_enum_type   failure_code;
    } set_evdo_pmp_info;

    qmi_wdsi_curr_data_system_status_type data_system_status;

    struct
    {
      uint32                          ep_id;
      uint8                           mux_id;
      uint8                           is_v6;
      boolean                         uplink_flow_ctrl;
    } flow_ctrl;

    struct
    {
      uint16    num_instances;
    } init_cb;

    struct
    {
      qmi_framework_common_msg_hdr_type    common_msg_hdr;
    } clid_cb;

    struct
    {
      qmi_framework_msg_hdr_type    msg_hdr;
      dsm_item_type             *   sdu_in;
    } cmd_hdlr_cb;

    struct
    {
      ps_iface_type              *iface_ptr;
      ps_iface_event_enum_type   event;
      ps_iface_event_info_u_type event_info;
      void                       *wds_sp;
    }wlan_evt_info;

    struct
    {
      ds_profile_event_etype          event;
      uint32                          profile_count;
      ds_profile_changes_info       * profiles_changes;
      void                          * user_data_ptr;
    }profile_evt_info;

#ifdef FEATURE_DATA_LTE
    qmi_wds_lte_attach_pdn_list_type lte_attach_pdn_list;
#endif /* FEATURE_DATA_LTE */
    ps_sys_throughput_info_list_type   * thrpt_info_list;

    ps_sys_roaming_disallowed_info_type  * roaming_info_list;

    ps_sys_event_outage_notification_type outage_info;
    
    ps_sys_dl_throughput_info_type     dl_thrpt_info;
    ps_sys_policy_refresh_status_type    policy_refresh_status;
    ps_sys_policy_available_info_type  * policy_avail_info;

    ps_sys_ul_dl_throughput_info_type  ul_dl_thrpt_info;

    ps_sys_configured_throughput_info_type  configured_thrpt_info;
    ps_sys_thrpt_status_type            dl_thrpt_reporting_status;

    struct
     {
       void              *cl_sp;
     }rev_ip_conn_info;

    ps_sys_event_3gpp_lte_attach_params_ex_type lte_params;
    ps_sys_pdn_throttle_info_type               pdn_throttle_info;

    ps_sys_pco_info_per_apn_type     apn_pco_list_reporting_status;

    ps_sys_msisdn_info_per_apn_type  apn_msisdn_reporting_status;

ps_sys_3gpp_rab_reject_info_type rab_reject_info;

    ps_sys_event_modem_asst_ka_status_info_type ps_keep_alive_info;

    ps_sys_event_3gpp_lte_attach_pdn_list_action_result attach_action_result;

    struct
    {
      ip_filter_type  cl_ip_info;
      void     *wds_sp;
      void     *cl_sp;
      uint32    handle;
    }ran_asst_media_adapt_cl_info;

  } data;
} qmi_wdsi_cmd_buf_type;

