/*===========================================================================
  FUNCTION QMI_WDSI_DEREG_APN_PCO_INFO_CHANGE()

  DESCRIPTION
    Deregister for event PS_SYS_EVENT_APN_PCO_INFO_CHANGE before
    client is released.

  PARAMETERS
    wds_sp        : service provided state pointer
    cl_sp         : client state pointer

  RETURN VALUE
    None

  DEPENDENCIES
    None

  SIDE EFFECTS
    None
===========================================================================*/
static void qmi_wdsi_dereg_apn_pco_info_change
(
  qmi_wdsi_state_type             * wds_sp,
  qmi_wdsi_client_state_type      * cl_sp
)
{
  int cnt_apn = 0;
/*- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -*/

  for(cnt_apn = 0; cnt_apn < QMI_WDS_NUM_APN_MAX; cnt_apn++)
  {
    if (0 == strcmp(qmi_wdsi_global.op_reserved_pco_apn_ref_cnt[cnt_apn].apn_name, 
                    cl_sp->pco_apn_name) &&
       (0 != qmi_wdsi_global.op_reserved_pco_apn_ref_cnt[cnt_apn].ref_cnt))
    {
      break;
    }
  }

  if(cnt_apn < QMI_WDS_NUM_APN_MAX)
  {
     qmi_wdsi_indication_deregister_event(PS_SYS_EVENT_APN_PCO_INFO_CHANGE, 
                                          cnt_apn, cl_sp, wds_sp);
  }
  else
  {
    LOG_MSG_ERROR_INT_0 ("qmi_wdsi_dereg_apn_pco_info_change(): APN not found!!");
  }
}

