  {
    return;
  }
  memset(indication,0,sizeof(wds_configured_throughput_info_ind_msg_v01));
  indication->ul_configured_throughput_valid  = TRUE;
  indication->dl_configured_throughput_valid  = TRUE;

  indication->ul_configured_throughput  = thrpt_info.ul_configured_throughput;
  indication->dl_configured_throughput  = thrpt_info.dl_configured_throughput;

